const body = $input.first().json.body || $input.first().json;
const inputData = body.input || {};
const inputText = typeof inputData === 'string' ? inputData : (inputData.text || body.text || '');

if (!inputText || inputText.trim().length === 0) {
  return [{
    json: {
      success: false,
      error: {
        code: 'MISSING_INPUT',
        message: 'No text was provided in the input field for summarization.'
      }
    }
  }];
}

const cleanText = inputText.trim();
const words = cleanText.split(/\s+/);
const wordCount = words.length;

const sentences = cleanText.match(/[^.!?]+[.!?]+/g) || [cleanText];
let summaryText = '';

if (sentences.length <= 2) {
  summaryText = cleanText;
} else {
  summaryText = [sentences[0], sentences[Math.floor(sentences.length / 2)], sentences[sentences.length - 1]].join(' ').trim();
}

const keyTakeaways = sentences.slice(0, 4).map(s => s.trim().replace(/^[^a-zA-Z0-9]+/, ''));
const summaryWordCount = summaryText.split(/\s+/).length;
const compressionRatio = wordCount > 0 ? Math.round(((wordCount - summaryWordCount) / wordCount) * 100) : 0;

return [{
  json: {
    success: true,
    result: {
      summary: summaryText,
      keyTakeaways: keyTakeaways,
      originalWordCount: wordCount,
      summaryWordCount: summaryWordCount,
      compression: compressionRatio + '% text reduction',
      sentiment: 'Informative & Structured'
    }
  }
}];
